local _, WFJ = ...
WFJ.Data.add("book", {
  ["b1127261f5d155f4"] = { "Le forze di Turalyon riuscirono a distruggere il Portale Oscuro, il varco mistico che collegava gli orchi al loro mondo natale, Draenor. Tagliata fuori dai rinforzi e lacerata dalle lotte interne, l'⟦Horde=Orda⟧ infine crollò su se stessa e cadde davanti alla potenza dell'⟦Alliance=Alleanza⟧.", "." },
  ["b123a1b21cf857cf"] = { "Giorno 6\n\nL'orso non è ancora tornato: devo avergliele suonate di santa ragione! Ma sento ancora il suo ringhio. Credo che stia aspettando che io muoia!\n\nA chiunque trovi questo diario: ho un compito per te. Uccidi quell'orso rognoso. Uccidilo, e riporta questo diario al mio amico Hammerfoot. Vorrà sapere cos'è successo.\n\nE prenditi la mia armatura. Ti servirà contro il vecchio ⟦Mangeclaw=Zampabianca⟧!", "." },
  ["b1aa9e1e7e1ff3f2"] = { "Nessa,\n\nche piacere avere tue notizie.\n\nLa raccolta di ossa e scaglie che mi hai mandato è incredibile. Non ho mai visto pesci di quelle dimensioni lontano dal continente. I pescatori di Rut'theran devono tirare su almeno una tonnellata di pesce al giorno!\n\nInvidio l'abbondanza delle loro pescate, ma sono anche un po' turbato. Possibile che il nostro nuovo albero del mondo faccia crescere i pesci fino a quelle dimensioni? E se è così, quali altri effetti potrebbe avere?\n\nDomande su cui riflettere,\n-Laird", "." },
  ["b1af00f0c42789ac"] = { "Nelle caverne di Maraudon vagano gli spiriti dei nostri primi Khan. I primi figli della nostra Madre e del nostro Padre, e i nostri più grandi condottieri: sono Gelk, Kolk, Magra, Maraudos e Veng. Ognuno di questi spiriti custodisce una delle gemme mancanti.", "." },
  ["b1e30e6aaffb0352"] = { "ATTENZIONE:\n\nResta in silenzio! Non guardare nessuno! Qualcuno potrebbe osservarti proprio in questo momento.\n\nMi chiamo Alamar Grimm, {name}. Addestro chi è disposto a cercare conoscenza e un potere più grande da... mondi lontani. Mi è stato chiesto di mettermi in contatto con te con discrezione e di informarti che posso insegnarti una vera forma di magia.\n\nQuando puoi, vieni a cercarmi nel retro di ⟦Anvilmar=Forgiamara⟧.\n\n-Alamar Grimm, istruttore degli stregoni", "." },
})
